  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Do I need Search Console if my developer already set it up?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, and you should hold your own access. Google describes it as a free service that helps you monitor, maintain and troubleshoot your site's presence in search, and it is the only place that reports Google's own data about your property. If your developer or agency owns the only verified property, ask to be added before anything else happens."
      }
    },
    {
      "@type": "Question",
      "name": "How often should I check it?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Google's own guidance is that there is no need to sign in every day, and that a monthly check, or a check after site changes, is enough. Weekly is reasonable if you are publishing actively. Daily checking mostly produces worry, because the newest data is incomplete and average position moves for reasons outside your control."
      }
    },
    {
      "@type": "Question",
      "name": "Why does my position look worse in Search Console than in my rank tracker?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Because they measure different things. Average position in Search Console is the average position of your topmost result across many queries and many searchers, and Google notes that results are specific to the time, place, device and recent history of the person searching. A rank tracker checks one query from one location on a schedule. Treat them as two instruments, not two verdicts."
      }
    },
    {
      "@type": "Question",
      "name": "What does it mean when a page says it is discovered but not indexed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It means Google knows the address exists and has chosen not to index it yet, or has not got to it. The usual causes are quality, duplication, thin content or a crawl decision rather than a technical block. Check for a self referencing canonical, confirm the page is linked internally, and improve the page rather than requesting indexing repeatedly."
      }
    },
    {
      "@type": "Question",
      "name": "Can Search Console tell me if I have been penalised?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "For manual actions, yes. The Manual Actions report shows whether Google has applied one and where. It cannot show algorithmic ranking changes, which appear as gradual or abrupt declines with no notification. If traffic falls and the Manual Actions and Security Issues reports are clean, the cause is usually competitive or intent related."
      }
    },
    {
      "@type": "Question",
      "name": "What should I export and keep?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Keep a monthly export of the Performance report by query and by page, and a monthly count of indexed versus excluded addresses. Over two or three quarters that history is the only dependable way to tell whether a change helped, because the interface keeps only a limited window and comparisons get muddled by seasonality."
      }
    }
  ]
}

